def evaluate_json(workspace: Path, spec_path: str | Path) -> dict[str, Any]:
    spec_file = Path(spec_path)
    if not spec_file.is_absolute():
        spec_file = workspace / spec_file
    spec = json.loads(spec_file.read_text(encoding="utf-8"))
